        @NotBlank @Size(max = 100) String user, @NotNull Long id) {
}

public record MovePersonRequest(@NotBlank @Size(max = 100) String sheet,
        @NotBlank @Size(max = 100) String user, @NotNull Long id,
        @NotNull @Pattern(regexp = "up|down") String direction) {
}

