        @NotNull LocalDate until) {
public PersonResponse undoTransfer(@Valid @RequestBody UndoTransferRequest req) {
    Person back = transfers.undo(req.sheet().trim(), req.user().trim(), req.id());
    return response(back.getSheetId(), back);
}

@PostMapping("/bulk-grade")
public BulkGradeResponse bulkGrade(@Valid @RequestBody BulkGradeRequest req) {
    List<PersonResponse> graded = service.bulkGrade(req.sheet().trim(), req.user().trim(), req.ids(), req.grade(),
            req.from()).stream().map(p -> response(req.sheet().trim(), p)).toList();
    return new BulkGradeResponse(graded.size(), graded);
}

@PostMapping("/bulk-retire")
public BulkRetireResponse bulkRetire(@Valid @RequestBody BulkRetireRequest req) {
    List<PersonResponse> retired = service.bulkRetire(req.sheet().trim(), req.user().trim(), req.ids(),
            req.date()).stream().map(p -> response(req.sheet().trim(), p)).toList();
    return new BulkRetireResponse(retired.size(), retired);
}

@PostMapping("/retire")
public PersonResponse retire(@Valid @RequestBody RetirePersonRequest req) {
    return response(req.sheet().trim(), service.retire(req.sheet().trim(), req.user().trim(), req.id(), req.date()));
}

@PostMapping("/unretire")
public PersonResponse unretire(@Valid @RequestBody UnretirePersonRequest req) {
    return response(req.sheet().trim(), service.unretire(req.sheet().trim(), req.user().trim(), req.id()));
}

/** Swap the person with the one above or below them in the list. */
@PostMapping("/move")
public PersonResponse move(@Valid @RequestBody MovePersonRequest req) {
    return response(req.sheet().trim(), service.move(req.sheet().trim(), req.user().trim(), req.id(),
            req.direction().equals("up")));
}

@PostMapping("/hold")
public PersonResponse hold(@Valid @RequestBody HoldPersonRequest req) {
    return response(req.sheet().trim(), service.hold(req.sheet().trim(), req.user().trim(), req.id(), req.from(), req.to()));
}


/**
 * Give each of the people a grade from a from-date (the sheet's today when none is given), in list
 * order, exactly as editing each with the person form would (name, terms and contact kept). All or none: a
 * person not on the sheet refuses the lot. A viewer may grade no one: each person is refused and
 * none is graded.
 */
@Transactional
public List<Person> bulkGrade(String sheetId, String user, List<Long> ids, String grade, LocalDate gradeFrom) {
    try {
        roles.refuseViewer(sheetId, user);
    } catch (ResponseStatusException e) {
        if (e.getStatusCode() == HttpStatus.FORBIDDEN) {
            return List.of();
        }
        throw e;
    }
    Set<Long> wanted = new HashSet<>(ids);
    List<Person> chosen = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
            .filter(p -> wanted.contains(p.getId())).toList();
    if (chosen.size() != wanted.size()) {
        throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet.");
    }
    return chosen.stream().map(p -> update(sheetId, user, p.getId(), p.getVersion(), p.getName(), grade,
            gradeFrom, p.termsOn(sheets.today(sheetId)), p.getContact())).toList();
}

/**
 * Retire each of the people from a date (the sheet's today when none is given), in list order,
 * exactly as retiring each from their row would. All or none: a person not on the sheet refuses
 * the lot. A viewer may retire no one: each person is refused and none is retired.
 */
@Transactional
public List<Person> bulkRetire(String sheetId, String user, List<Long> ids, LocalDate date) {
    try {
        roles.refuseViewer(sheetId, user);
    } catch (ResponseStatusException e) {
        if (e.getStatusCode() == HttpStatus.FORBIDDEN) {
            return List.of();
        }
        throw e;
    }
    Set<Long> wanted = new HashSet<>(ids);
    List<Person> chosen = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
            .filter(p -> wanted.contains(p.getId())).toList();
    if (chosen.size() != wanted.size()) {
        throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet.");
    }
    return chosen.stream().map(p -> retire(sheetId, user, p.getId(), date)).toList();
}

/**
 * Swap the person with the one above ({@code up}) or below them in the list; the top person
 * cannot move up nor the bottom one down (409).
 */
@Transactional
public Person move(String sheetId, String user, long id, boolean up) {
    roles.refuseViewer(sheetId, user);
    sheets.refuseIfArchived(sheetId);
    List<Person> listed = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
    int at = -1;
    for (int i = 0; i < listed.size(); i++) {
        if (listed.get(i).getId() == id) {
